def fibonacci(n):
    """
    Kuanza na 0 na 1, mlolongo wa Fibonacci unajumuisha nambari zote zinazofuata kama jumla ya nambari mbili zilizotangulia.
    """
    if n <= 0:
        return "Muda wa Fibonacci hauwezi kuwa hasi au sifuri"
    elif n == 1:
        return 0
    elif n == 2:
        return 1
    else:
        fib_sequence = [0, 1]
        while len(fib_sequence) < n:
            fib_sequence.append(fib_sequence[-1] + fib_sequence[-2])
        return fib_sequence

